"""v53: F6 TEST -> Numerology Takeaways. The conclusions, not the workings: the lean's record this season (graded as games land)
and out of sample, this week's calls game by game with the associations behind each, the strong plays written out, the
associations that have actually held up season over season, the ones to ignore, last week reviewed, and the players.
Rerunnable (guarded)."""
import os, sys
P = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'dashboard_template.html')
s = open(P, encoding='utf-8').read()
if 'function numTake()' in s:
    print('already applied'); sys.exit()
def rep(old, new, n=1):
    global s
    c = s.count(old); assert c == n, ('match count %d != %d for: %s' % (c, n, old[:100])); s = s.replace(old, new)

rep("{id:'numer',nfl:true,label:'Numerology',", "{id:'numtake',nfl:true,label:'Numerology Takeaways',desc:'the conclusions: how the numerology lean has actually graded this season and out of sample, this week\\'s call on every game with the associations behind it, the strong plays written out, what has held up season over season and what to ignore, last week reviewed, the players',c:'test',sub:'numtake'},{id:'numer',nfl:true,label:'Numerology',")
rep('<div id="test" hidden><div id="numer" hidden></div>', '<div id="test" hidden><div id="numtake" hidden></div><div id="numer" hidden></div>')
rep("if(it.c==='test'){['numer','bestpicks',", "if(it.c==='test'){['numtake','numer','bestpicks',")
rep("['test',numerology],", "['test',numerology],['test',numTake],")
rep(" numer:{what:'Gematria, tested instead of trusted.", " numtake:{what:'What the numbers actually say \\u2014 and whether they have been right. The lean (every match a game carries, folded by each association\\'s own record, team proxies out) graded this season as games land and out of sample on past seasons; this week\\'s call on every game with the associations behind it; the plays worth a look written out; the associations that have held season over season; the ones to ignore; last week reviewed; the players.',how:['a call is only as good as its record line \\u2014 read the season scoreboard first','strong = |lean| \\u2265 0.03 \\u00b7 backed by = the associations that pushed the call, each with its record since 2024','held up = positive on winners in every season it has 10+ games \\u00b7 proxies (carried by three clubs or fewer) never count']},\n numer:{what:'Gematria, tested instead of trusted.")

# per-season splits on the engine
rep("const t=T[tk]=T[tk]||{k,nk:nn.k,c,side:vals.N!=null?'N':(vals.A!=null&&vals.H!=null?'S':'H'),win:{n:0,w:0},ats:{n:0,w:0},ou:{n:0,w:0},teams:new Set()};",
    "const t=T[tk]=T[tk]||{k,nk:nn.k,c,side:vals.N!=null?'N':(vals.A!=null&&vals.H!=null?'S':'H'),win:{n:0,w:0},ats:{n:0,w:0},ou:{n:0,w:0},teams:new Set(),by:{}};const sb=t.by[r[NX.season]]=t.by[r[NX.season]]||{n:0,w:0};")
rep("const pickHome=mH;t.teams.add(pickHome?r[NX.home]:r[NX.away]);t.win.n++;if(pickHome?hw:aw)t.win.w++;",
    "const pickHome=mH;t.teams.add(pickHome?r[NX.home]:r[NX.away]);t.win.n++;sb.n++;if(pickHome?hw:aw){t.win.w++;sb.w++}")
rep("}else{t.teams.add(r[NX.home]);t.win.n++;if(hw)t.win.w++;",
    "}else{t.teams.add(r[NX.home]);t.win.n++;sb.n++;if(hw){t.win.w++;sb.w++}")

rep("/* ---------------- v48: BEST PICKS", r"""/* ---------------- v53: NUMEROLOGY TAKEAWAYS ---------------- */
const numLabel=m=>`${m.e.l} <b>${esc(m.e.text)}</b> = ${m.v} <span class="mini dim">${cshort(m.cl)}</span> = ${m.nn.l}`;
const numRec=t=>`${t.win.w}-${t.win.n-t.win.w} (${(100*t.win.p).toFixed(0)}%)`;
function numTake(){const el=$('#numtake');if(!el)return;const wk=G.week;const S=J.season||2026;const NG=NUMG();const A=numAssoc();const AS=numAssoc(S);   /* AS = fit on seasons before this one: the honest grader for this season */
  const minN=25;const th=.03;
  /* 1 · the scoreboard: this season's lean picks graded as games land (fit on prior seasons), plus last season out of sample */
  const season=NG.filter(r=>r[NX.season]===S&&r[NX.week]<=wk);const graded=season.filter(r=>r[NX.as]!=null&&r[NX.hs]!=null&&r[NX.as]!==r[NX.hs]);
  const pickOf=(r,fit)=>{const L=leanOf(r,fit,minN);if(!L.lean)return null;const side=L.lean>0?r[NX.home]:r[NX.away];return {side,strength:Math.abs(L.lean),strong:Math.abs(L.lean)>=th,L}};
  const g=graded.map(r=>({r,p:pickOf(r,AS)})).filter(x=>x.p);const won=x=>x.p.side===(x.r[NX.hs]>x.r[NX.as]?x.r[NX.home]:x.r[NX.away]);const covered=x=>{const sp=x.r[NX.spread];if(sp==null)return null;const m=x.r[NX.hs]-x.r[NX.as];if(m===sp)return null;return x.p.side===x.r[NX.home]?m>sp:m<sp};
  const rec=X=>{const w=X.filter(won).length;return {n:X.length,w,l:X.length-w}};const recA=X=>{const Y=X.filter(x=>covered(x)!=null);const w=Y.filter(x=>covered(x)).length;return {n:Y.length,w,l:Y.length-w}};
  const all=rec(g),strong=rec(g.filter(x=>x.p.strong)),allA=recA(g),strongA=recA(g.filter(x=>x.p.strong));const lastWk=Math.max(0,...graded.map(r=>r[NX.week]));const lw=g.filter(x=>x.r[NX.week]===lastWk);const lwr=rec(lw);
  const W=numWalk();const prev=W[S-1];const hb=graded.length?graded.filter(r=>r[NX.hs]>r[NX.as]).length/graded.length:null;
  const pct=o=>o.n?(100*o.w/o.n).toFixed(1)+'%':'—';const tone=o=>o.n<10?'':o.w/o.n>=.55?'g':o.w/o.n<=.45?'r':'';
  const k=(t,v,s_,cls='')=>`<div class="kpi ${cls}"><div class="k">${t}</div><div class="v">${v}</div><div class="s">${s_}</div></div>`;
  const kp=`<div class="kpis">${k(`${S} · the lean, winners`,`${all.w}-${all.l}`,`${pct(all)} · ${all.n} calls through week ${lastWk} · home side ${hb!=null?(100*hb).toFixed(1)+'%':'—'}`,tone(all))}${k(`${S} · strong calls`,`${strong.w}-${strong.l}`,`${pct(strong)} · |lean| ≥ ${th}`,tone(strong))}${k(`${S} · against the spread`,`${allA.w}-${allA.l}`,`${pct(allA)} · strong ${strongA.w}-${strongA.l} · break-even 52.4%`,tone(allA))}${k(`week ${lastWk}`,`${lwr.w}-${lwr.l}`,`${pct(lwr)} · last graded week`,tone(lwr))}${prev?k(`${S-1} · out of sample`,`${prev.w}-${prev.n-prev.w}`,`${prev.n?(100*prev.w/prev.n).toFixed(1)+'%':'—'} · strong ${prev.strong.w}-${prev.strong.n-prev.strong.w} · fit on ${prev.fit} games`,tone({n:prev.n,w:prev.w})):''}</div>`;
  const edgeTxt=(o,base)=>o.n<20?`too early to say (${o.n} calls)`:o.w/o.n-base>=.03?`running ${((o.w/o.n-base)*100).toFixed(1)} points above the home-side baseline`:o.w/o.n-base<=-.03?`running ${((base-o.w/o.n)*100).toFixed(1)} points below the home-side baseline`:'running with the home-side baseline — the coin';
  const verdict=`<div class="panel"><h3>the verdict <span>read this before anything below</span></h3><p style="font-size:13px;line-height:1.6;margin:4px 0">This season the numerology lean is <b>${all.w}-${all.l}</b> on winners (${pct(all)}) and <b>${allA.w}-${allA.l}</b> against the spread, ${edgeTxt(all,hb||.5)}. Strong calls are <b>${strong.w}-${strong.l}</b>. ${prev?`Last season, fit only on the season before it, it went <b>${prev.w}-${prev.n-prev.w}</b> (${(100*prev.w/Math.max(1,prev.n)).toFixed(1)}%) against a home baseline of ${(100*prev.home.w/Math.max(1,prev.home.n)).toFixed(1)}%${prev.strong.n?`, strong calls <b>${prev.strong.w}-${prev.strong.n-prev.strong.w}</b>`:''}.`:''} ${all.n+ (prev?prev.n:0)<150?'That is not enough games to separate a real edge from variance — treat every call below as a tiebreaker at most, never as the reason to bet.':(all.w/Math.max(1,all.n)>=.55&&prev&&prev.w/Math.max(1,prev.n)>=.55?'Two seasons above the baseline is worth a position-sized look; the strong calls are where it has been best.':'The record does not clear the baseline by enough to bet on its own; use the calls as a tiebreaker when the model and the market already lean the same way.')}</p></div>`;
  /* 2 · this week's calls */
  const gs=GAMES(wk);const rows=gs.map(x=>{const r=NG.find(q=>q[NX.season]===S&&q[NX.week]===wk&&q[NX.away]===x[GM.vis]&&q[NX.home]===x[GM.home])||[S,wk,x[GM.date],x[GM.day],'',x[GM.vis],x[GM.home],null,null,null,null,'','','','','','','','','',null,null,null,'REG'];const p=pickOf(r,A);const L=p?p.L:leanOf(r,A,minN);const done=r[NX.as]!=null&&r[NX.hs]!=null;const win=done&&p?p.side===(r[NX.hs]>r[NX.as]?r[NX.home]:r[NX.away]):null;
    const sideOf=u=>u.m.t.side==='H'?r[NX.home]:u.m.e.side==='H'?r[NX.home]:r[NX.away];const pushes=u=>p&&((u.w>0&&sideOf(u)===p.side)||(u.w<0&&sideOf(u)!==p.side));const backing=L.used.filter(pushes).sort((a,b)=>Math.abs(b.w)-Math.abs(a.w)).slice(0,3);const against=L.used.filter(u=>!pushes(u)).length;return {x,r,p,L,done,win,backing,against}}).sort((a,b)=>(b.p?b.p.strength:0)-(a.p?a.p.strength:0));
  const calls=`<div class="panel"><h3>this week's calls — week ${wk} <span>every game, the lean, and the associations that pushed it (each with its record since 2024, proxies excluded) · sorted by strength · no call = the matches cancel or none clears ${minN} games</span></h3><table><thead><tr><th>game</th><th>kick</th><th>spread</th><th>the call</th><th>strength</th><th>backed by</th><th>against</th><th>result</th></tr></thead><tbody>${rows.map(({x,r,p,L,done,win,backing,against})=>`<tr><td>${tcell(x[GM.vis])} <span class="dim">@</span> ${tcell(x[GM.home])}</td><td class="mini">${x[GM.day]} ${x[GM.time]||''}</td><td class="mono mini">${r[NX.spread]!=null?`${r[NX.home]} ${r[NX.spread]>0?'-':'+'}${Math.abs(r[NX.spread])}`:'—'}</td><td>${p?`<b style="color:${p.strong?'var(--green)':'var(--txt)'}">${tcell(p.side)}</b>${p.strong?' <span class="mini" style="color:var(--green)">strong</span>':' <span class="mini dim">lean</span>'}`:'<span class="dim">no call</span>'}</td><td class="num">${p?p.strength.toFixed(3):'—'}</td><td class="mini">${backing.map(u=>`${u.w<0?'<span style="color:var(--red)">fade</span> ':''}${numLabel(u.m)} <span style="color:${u.w<0?'var(--red)':'var(--green)'}">${numRec(u.m.t)}</span>`).join('<br>')||'<span class="dim">—</span>'}</td><td class="num">${against||''}</td><td>${done?(win==null?'<span class="dim">—</span>':`<span class="res ${win?'W':'L'}">${win?'W':'L'}</span> <span class="mini">${r[NX.as]}-${r[NX.hs]}</span>`):'<span class="mini dim">open</span>'}</td></tr>`).join('')}</tbody></table></div>`;
  /* 3 · the plays, written out */
  const plays=rows.filter(q=>q.p&&q.p.strong);
  const playTxt=({x,r,p,L,backing})=>{const opp=p.side===r[NX.home]?r[NX.away]:r[NX.home];return `<div class="panel" style="border-left:3px solid var(--green)"><h3>${tcell(p.side)} <span class="mini dim">${p.side===r[NX.home]?'vs':'@'} ${opp} · ${x[GM.day]} ${x[GM.time]||''}${r[NX.spread]!=null?' · '+r[NX.home]+' '+(r[NX.spread]>0?'-':'+')+Math.abs(r[NX.spread]):''}</span> <span>lean ${p.strength.toFixed(3)}</span></h3><p style="font-size:13px;line-height:1.6;margin:4px 0">${backing.map(u=>`${u.w<0?opp+'’s ':''}${u.m.e.l==='stadium'||u.m.e.l==='stadium city'||u.m.e.l==='stadium state'?'the building':u.m.e.l} <b>${esc(u.m.e.text)}</b> reads <b>${u.m.v}</b> in ${u.m.cl}, which is this game’s <b>${u.m.nn.l}</b>; that association has gone <b>${numRec(u.m.t)}</b> for the matched side since 2024${u.m.t.by[S]&&u.m.t.by[S].n?` (${u.m.t.by[S].w}-${u.m.t.by[S].n-u.m.t.by[S].w} this season)`:''}${u.w<0?` — a losing association on ${opp}’s side, so it fades ${opp}`:''}`).join('. ')}.${L.used.length>backing.length?` ${L.used.length-backing.length} weaker association${L.used.length-backing.length>1?'s point':' points'} the other way.`:''}</p></div>`};
  const playsHtml=`<div class="panel"><h3>the plays <span>strong calls, written out · ${plays.length} this week</span></h3>${plays.length?plays.map(playTxt).join(''):'<p class="note">no strong call this week — nothing clears |lean| '+th+'</p>'}</div>`;
  /* 4 · what has held up, what to ignore */
  const seasons=[...new Set(NG.filter(r=>r[NX.as]!=null).map(r=>r[NX.season]))].sort();
  const T=Object.values(A.T).filter(t=>t.nt>=4&&t.win.n>=minN);const held=T.filter(t=>seasons.every(sn=>!t.by[sn]||t.by[sn].n<10||t.by[sn].w/t.by[sn].n>.5)&&t.win.p>=.55).sort((a,b)=>b.win.z-a.win.z).slice(0,12);
  const ignore=T.filter(t=>t.win.p<=.42).sort((a,b)=>a.win.z-b.win.z).slice(0,8);const prox=Object.values(A.T).filter(t=>t.nt<4&&t.win.n>=minN&&Math.abs(t.win.z)>=2).sort((a,b)=>Math.abs(b.win.z)-Math.abs(a.win.z)).slice(0,6);
  const trow=t=>`<tr><td>${ENT_L[t.k]} = ${NUM_K[t.nk]} <span class="mini dim">${cshort(CIPH_L[t.c])}</span></td><td class="mini">${t.side==='S'?'matched side':'home side'}</td><td class="num">${t.nt}</td><td class="num">${t.win.n}</td><td class="num"><b style="color:${t.win.p>=.55?'var(--green)':t.win.p<=.45?'var(--red)':'var(--txt)'}">${numRec(t)}</b></td>${seasons.map(sn=>`<td class="num mini">${t.by[sn]?`${t.by[sn].w}-${t.by[sn].n-t.by[sn].w}`:'—'}</td>`).join('')}<td class="num">${t.win.z>0?'+':''}${t.win.z.toFixed(1)}</td></tr>`;
  const thead=`<thead><tr><th>association</th><th>graded as</th><th>clubs</th><th>n</th><th>record</th>${seasons.map(sn=>`<th>${sn}</th>`).join('')}<th>z</th></tr></thead>`;
  const held_=`<div class="nmgrid"><div class="panel"><h3>what has held up <span>55%+ on winners overall and never under 50% in any season with 10+ games, carried by four or more clubs · ${held.length} of ${T.length}</span></h3><table>${thead}<tbody>${held.map(trow).join('')||'<tr><td colspan="9" class="dim">nothing clears the bar</td></tr>'}</tbody></table></div>
    <div class="panel"><h3>what to ignore <span>under 42% on winners — the matched side has been losing, which is as uninformative as winning once you have ${T.length} of these · and the proxies: associations that are really one or two clubs</span></h3><table>${thead}<tbody>${ignore.map(trow).join('')}${prox.map(t=>`<tr style="opacity:.6"><td>${ENT_L[t.k]} = ${NUM_K[t.nk]} <span class="mini dim">${cshort(CIPH_L[t.c])}</span> <span class="mini" style="color:#e8b100">proxy: ${[...t.teams].join(', ')}</span></td><td class="mini">${t.side==='S'?'matched side':'home side'}</td><td class="num">${t.nt}</td><td class="num">${t.win.n}</td><td class="num">${numRec(t)}</td>${seasons.map(sn=>`<td class="num mini">${t.by[sn]?`${t.by[sn].w}-${t.by[sn].n-t.by[sn].w}`:'—'}</td>`).join('')}<td class="num">${t.win.z>0?'+':''}${t.win.z.toFixed(1)}</td></tr>`).join('')}</tbody></table></div></div>`;
  /* 5 · last week reviewed */
  const review=lw.length?`<div class="panel"><h3>week ${lastWk} reviewed <span>every call the lean made, graded · ${lwr.w}-${lwr.l}</span></h3><table><thead><tr><th>game</th><th>score</th><th>the call</th><th>strength</th><th>result</th><th>what pushed it</th></tr></thead><tbody>${lw.sort((a,b)=>b.p.strength-a.p.strength).map(x=>{const sideOf=u=>u.m.t.side==='H'?x.r[NX.home]:u.m.e.side==='H'?x.r[NX.home]:x.r[NX.away];const b=x.p.L.used.filter(u=>(u.w>0&&sideOf(u)===x.p.side)||(u.w<0&&sideOf(u)!==x.p.side)).sort((a,c)=>Math.abs(c.w)-Math.abs(a.w)).slice(0,2);return `<tr><td>${tcell(x.r[NX.away])} <span class="dim">@</span> ${tcell(x.r[NX.home])}</td><td class="mono">${x.r[NX.as]}-${x.r[NX.hs]}</td><td>${tcell(x.p.side)}${x.p.strong?' <span class="mini" style="color:var(--green)">strong</span>':''}</td><td class="num">${x.p.strength.toFixed(3)}</td><td><span class="res ${won(x)?'W':'L'}">${won(x)?'W':'L'}</span>${covered(x)!=null?` <span class="mini">${covered(x)?'covered':'did not cover'}</span>`:''}</td><td class="mini">${b.map(u=>(u.w<0?'<span style="color:var(--red)">fade</span> ':'')+numLabel(u.m)+' <span style="color:'+(u.w<0?'var(--red)':'var(--green)')+'">'+numRec(u.m.t)+'</span>').join('<br>')}</td></tr>`}).join('')}</tbody></table></div>`:'';
  /* 6 · the players */
  const prows=[];gs.forEach(x=>{const rr=NG.find(r=>r[NX.season]===S&&r[NX.week]===wk&&r[NX.away]===x[GM.vis]&&r[NX.home]===x[GM.home]);const nn=rr?gameNums(rr):dateNums(x[GM.date]);const d=new Map();nn.forEach(y=>{if(!d.has(y.v))d.set(y.v,y.l)});[x[GM.vis],x[GM.home]].forEach(t=>{(J.matchups||[]).filter(m=>m.team===t&&/^(QB|RB1|RB2|WR1|WR2|WR3|TE1)$/.test(m.slot)).forEach(m=>{const gg=gemAll(m.player);const hits=CIPH.filter(([id])=>d.has(gg[id])).map(([id,l])=>`${cshort(l)} ${gg[id]} = ${d.get(gg[id])}`);if(hits.length>=2)prows.push({m,t,o:t===x[GM.vis]?'@'+x[GM.home]:'vs '+x[GM.vis],hits})})})});prows.sort((a,b)=>b.hits.length-a.hits.length);
  const players=`<div class="panel"><h3>the players <span>starters whose name lands on two or more of their game's numbers · ${prows.length} this week · the touchdown test on the Numerology tab says names have not separated scorers from non-scorers (lifts near ×1 on every cipher with a real sample) — this is a watch list, not a pick list</span></h3><table><thead><tr><th>player</th><th>tm</th><th>slot</th><th>opp</th><th>hits</th><th>which</th></tr></thead><tbody>${prows.slice(0,25).map(r=>`<tr><td class="plink" data-p="${esc(r.m.player)}">${esc(r.m.player)}</td><td>${tcell(r.t)}</td><td>${slotchip(r.m.slot)}</td><td>${oppcell(r.o.replace('vs ',''))}</td><td class="num"><b>${r.hits.length}</b></td><td class="mini">${r.hits.join(' · ')}</td></tr>`).join('')||'<tr><td colspan="6" class="dim">none with two hits</td></tr>'}</tbody></table></div>`;
  el.innerHTML=kp+verdict+calls+playsHtml+held_+review+players;sortableAll(el)}
/* ---------------- v48: BEST PICKS""")
s = s.replace("Object.assign(NOTES,{v52:", "Object.assign(NOTES,{v53:['v53','F6 TEST \\u2192 Numerology Takeaways: the verdict and the season scoreboard (the lean graded as games land, fit on prior seasons), this week\\'s call on every game with the associations behind it, the strong plays written out, what has held up season over season, what to ignore, last week reviewed, the players'],v52:", 1)
